//! Go-compatible public CLI artifacts. The data is generated by real immutable
//! Go, and the shell protocol executes here without a Go runtime dependency.
use serde::Deserialize;
use std::{collections::BTreeMap, sync::LazyLock};

#[derive(Deserialize)]
pub struct Artifacts {
    pub help: BTreeMap<String, String>,
    pub completions: BTreeMap<String, String>,
    pub manpages: BTreeMap<String, String>,
    pub config_keys: Vec<String>,
    pub commands: Vec<Command>,
}

#[derive(Deserialize)]
pub struct Command {
    pub path: String,
    pub name: String,
    pub short: String,
    pub aliases: Option<Vec<String>>,
    pub valid_args: Option<Vec<String>>,
    pub arg_aliases: Option<Vec<String>>,
    pub hidden: bool,
    pub deprecated: String,
    pub available: bool,
    pub disable_flag_parsing: bool,
    pub dynamic: String,
    pub local_flags: Vec<Flag>,
    pub persistent_flags: Vec<Flag>,
}

#[derive(Deserialize)]
pub struct Flag {
    pub name: String,
    pub shorthand: String,
    pub usage: String,
    #[serde(rename = "type")]
    pub kind: String,
    pub no_opt_default: String,
    pub hidden: bool,
    pub deprecated: String,
    pub annotations: Option<BTreeMap<String, Vec<String>>>,
}

pub static DATA: LazyLock<Artifacts> = LazyLock::new(|| {
    serde_json::from_str(include_str!("../../../testdata/port/cli/artifacts.json"))
        .expect("verified Go CLI artifact schema")
});

/// A local flag the Rust CLI has and the frozen Go artifacts (`artifacts.json`,
/// which must stay byte-identical) do not. The overlay adds it to the flag
/// inventory (help parsing, shell completion), to the `--help` page and to the
/// generated manual page, so the public surface documents it.
/// `crates/symvault-cli/tests/rust_only_flags.rs` pins the exact lines it adds,
/// and the Go parity checks (`cli_generate_manpages`, `cli_artifacts_contract.py`)
/// declare the same additions.
pub struct RustOnlyFlag {
    pub path: &'static str,
    pub name: &'static str,
    /// pflag type name shown in help (`strings`, `string`, ...).
    pub help_type: &'static str,
    /// pflag type recorded in the flag inventory (`stringSlice`, ...).
    pub kind: &'static str,
    /// Default shown by the manual page (`[]`, `\"\"`, ...).
    pub man_default: &'static str,
    pub usage: &'static str,
}

pub const RUST_ONLY_FLAGS: &[RustOnlyFlag] = &[
    RustOnlyFlag {
        path: "symvault run",
        name: "broker-templates",
        help_type: "strings",
        kind: "stringSlice",
        man_default: "=[]",
        usage: "With --broker: inject credentials only for these templates (comma-separated, built-in or vault-local names); other template hosts are treated as hosts without a template",
    },
    RustOnlyFlag {
        path: "symvault broker",
        name: "templates",
        help_type: "strings",
        kind: "stringSlice",
        man_default: "=[]",
        usage: "Inject credentials only for these templates (comma-separated, built-in or vault-local names); other template hosts are treated as hosts without a template",
    },
];

static RUST_ONLY_INVENTORY: LazyLock<Vec<(&'static str, Flag)>> = LazyLock::new(|| {
    RUST_ONLY_FLAGS
        .iter()
        .map(|extra| {
            (
                extra.path,
                Flag {
                    name: extra.name.to_owned(),
                    shorthand: String::new(),
                    usage: extra.usage.to_owned(),
                    kind: extra.kind.to_owned(),
                    no_opt_default: String::new(),
                    hidden: false,
                    deprecated: String::new(),
                    annotations: None,
                },
            )
        })
        .collect()
});

/// The `--help` page of `path`: the frozen Go page plus the Rust-only flags.
pub fn help_page(path: &str) -> Option<std::borrow::Cow<'static, str>> {
    let page = DATA.help.get(path)?;
    let extras: Vec<_> = RUST_ONLY_FLAGS.iter().filter(|f| f.path == path).collect();
    if extras.is_empty() {
        return Some(std::borrow::Cow::Borrowed(page));
    }
    let mut lines: Vec<String> = page.split_inclusive('\n').map(str::to_owned).collect();
    let start = lines.iter().position(|l| l == "Flags:\n")? + 1;
    let end = start + lines[start..].iter().position(|l| l == "\n")?;
    // cobra aligns every usage text at one column; `help for` is always there.
    let column = lines[start..end]
        .iter()
        .find_map(|line| line.find("help for "))?;
    for extra in extras {
        let label = format!("--{} {}", extra.name, extra.help_type);
        assert!(
            label.len() + 9 <= column,
            "{label} overflows the help column"
        );
        let line = format!("      {label:<width$}{}\n", extra.usage, width = column - 6);
        let end = start + lines[start..].iter().position(|l| l == "\n")?;
        let at = lines[start..end]
            .iter()
            .position(|existing| help_flag_name(existing).is_some_and(|name| name > extra.name))
            .map_or(end, |offset| start + offset);
        lines.insert(at, line);
    }
    Some(std::borrow::Cow::Owned(lines.concat()))
}

/// Long name of one `Flags:` line (`  -e, --env stringArray   ...`).
fn help_flag_name(line: &str) -> Option<&str> {
    let rest = line.trim_start().strip_prefix("-")?;
    let rest = if rest.starts_with('-') {
        rest
    } else {
        rest.split_once(", ")?.1.strip_prefix('-')?
    };
    rest.strip_prefix('-')?.split(' ').next()
}

/// The manual page `name` (`symvault-run.1`): the frozen Go page plus the
/// Rust-only flags in its `OPTIONS` section, in cobra's alphabetical order.
pub fn manpage(name: &str, page: &str) -> String {
    let path = name
        .strip_suffix(".1")
        .map(|stem| stem.replace('-', " "))
        .unwrap_or_default();
    let mut page = page.to_owned();
    for extra in RUST_ONLY_FLAGS.iter().filter(|f| f.path == path) {
        let Some(head) = page.find("\n.SH OPTIONS\n") else {
            continue;
        };
        let body_start = head + "\n.SH OPTIONS\n".len();
        let body_end = body_start + page[body_start..].find("\n\n\n.SH ").unwrap_or(0);
        let entry = format!(
            "\\fB--{}\\fP{}\n\t{}",
            extra.name, extra.man_default, extra.usage
        );
        let mut entries: Vec<String> = page[body_start..body_end]
            .split("\n\n.PP\n")
            .map(str::to_owned)
            .collect();
        let at = entries
            .iter()
            .position(|existing| man_flag_name(existing).is_some_and(|n| n > extra.name))
            .unwrap_or(entries.len());
        entries.insert(at, entry);
        page.replace_range(body_start..body_end, &entries.join("\n\n.PP\n"));
    }
    page
}

/// Long name of one manual `OPTIONS` entry (`\fB-e\fP, \fB--env\fP=[]`).
fn man_flag_name(entry: &str) -> Option<&str> {
    let first = entry.lines().next()?;
    let (_, rest) = first.split_once("\\fB--")?;
    rest.split("\\fP").next()
}

/// The generated description advertises the actual resolved config location.
/// Keep the environment-derived path live rather than embedding capture HOME.
pub fn render(text: &str) -> std::borrow::Cow<'_, str> {
    if text.contains("__CONFIG_PATH__") {
        std::borrow::Cow::Owned(
            text.replace(
                "__CONFIG_PATH__",
                &symvault_core::config::PathResolver::new()
                    .config_path()
                    .to_string_lossy(),
            ),
        )
    } else {
        std::borrow::Cow::Borrowed(text)
    }
}

pub fn root() -> &'static Command {
    DATA.commands
        .iter()
        .find(|c| c.path == "symvault")
        .expect("root artifact")
}

/// Go `strconv.Quote` for UTF-8 flag diagnostics. Duration errors intentionally
/// retain `time`'s different byte-oriented quoting in the core duration parser.
pub fn quote_go_string(value: &str) -> String {
    symvault_core::go_quote(value)
}

/// Go `%q` of bytes that may not be UTF-8 (an environment value): each invalid
/// byte is written `\xNN`, where Go prints the byte and not U+FFFD.
pub fn quote_go_bytes(bytes: &[u8]) -> String {
    let mut quoted = String::from("\"");
    let mut rest = bytes;
    while !rest.is_empty() {
        match std::str::from_utf8(rest) {
            Ok(valid) => {
                quoted.push_str(&inner_quote(valid));
                break;
            }
            Err(error) => {
                let (valid, tail) = rest.split_at(error.valid_up_to());
                quoted.push_str(&inner_quote(std::str::from_utf8(valid).unwrap_or_default()));
                let bad = error.error_len().unwrap_or(tail.len());
                for byte in &tail[..bad] {
                    quoted.push_str(&format!("\\x{byte:02x}"));
                }
                rest = &tail[bad..];
            }
        }
    }
    quoted.push('"');
    quoted
}

/// [`quote_go_string`] without the surrounding quotes.
fn inner_quote(value: &str) -> String {
    let quoted = quote_go_string(value);
    quoted[1..quoted.len() - 1].to_owned()
}

pub fn children(command: &Command) -> impl Iterator<Item = &'static Command> {
    let prefix = format!("{} ", command.path);
    DATA.commands.iter().filter(move |c| {
        c.path
            .strip_prefix(&prefix)
            .is_some_and(|rest| !rest.contains(' '))
    })
}

pub fn child(command: &Command, name: &str) -> Option<&'static Command> {
    children(command).find(|c| {
        c.name == name
            || c.aliases
                .as_ref()
                .is_some_and(|a| a.iter().any(|a| a == name))
    })
}

pub fn flags(command: &'static Command) -> Vec<&'static Flag> {
    let mut inherited = BTreeMap::new();
    let mut scope = root().path.clone();
    for part in command.path.split(' ').skip(1) {
        if let Some(parent) = DATA.commands.iter().find(|c| c.path == scope) {
            for flag in &parent.persistent_flags {
                inherited.insert(flag.name.as_str(), flag);
            }
        }
        scope.push(' ');
        scope.push_str(part);
    }
    let mut local = BTreeMap::new();
    let extras = RUST_ONLY_INVENTORY
        .iter()
        .filter(|(path, _)| *path == command.path)
        .map(|(_, flag)| flag);
    for flag in command
        .persistent_flags
        .iter()
        .chain(&command.local_flags)
        .chain(extras)
    {
        inherited.remove(flag.name.as_str());
        local.insert(flag.name.as_str(), flag);
    }
    inherited.into_values().chain(local.into_values()).collect()
}

pub fn flag(command: &'static Command, word: &str) -> Option<&'static Flag> {
    let word = word.split('=').next()?;
    if let Some(name) = word.strip_prefix("--") {
        flags(command).into_iter().find(|f| f.name == name)
    } else {
        let name = word.strip_prefix('-')?;
        flags(command)
            .into_iter()
            .find(|f| !f.shorthand.is_empty() && f.shorthand == name)
    }
}

/// Help parsing follows Cobra's flag values and separator. Invalid flags stay
/// in the ordinary parser path; a help flag cannot hide a malformed argument.
pub fn flag_help(args: &[std::ffi::OsString]) -> Option<&'static str> {
    if !args
        .iter()
        .any(|a| a == "--help" || a == "-h" || a.to_str().is_some_and(|s| s.starts_with("--help=")))
    {
        return None;
    }
    if unknown_first_command(args) {
        // cobra's `Find` fails with `unknown command` (exit 1), never the root
        // help; the regular path reports it.
        return None;
    }
    let mut selected = root();
    let mut seen = Vec::new();
    let mut help = false;
    // cobra's `Find` never sees a bare `-h` / `--help` as the help flag: it takes the
    // next word as its value, so that word names no command.
    let mut swallow_next = false;
    let mut resolved = false;
    let mut i = 1;
    while let Some(word) = args.get(i) {
        let word = word.to_str()?;
        if word == "--" {
            break;
        }
        let swallowed = std::mem::take(&mut swallow_next);
        if word.starts_with('-') {
            swallow_next = !swallowed && (word == "-h" || word == "--help");
            let f = flag(selected, word)?;
            let inline = word.split_once('=').map(|(_, v)| v);
            let value = if let Some(v) = inline {
                v
            } else if f.no_opt_default.is_empty() {
                i += 1;
                args.get(i)?.to_str()?
            } else {
                &f.no_opt_default
            };
            if f.kind == "bool" {
                let enabled = crate::intake_commands::parse_bool(value).ok()?;
                if f.name == "help" {
                    help = enabled;
                }
            } else if matches!(f.kind.as_str(), "int" | "int64" | "uint" | "uint64") {
                if f.kind.starts_with('u') {
                    value.parse::<u64>().ok()?;
                } else {
                    value.parse::<i64>().ok()?;
                }
            } else if f.kind == "duration" {
                symvault_core::config::parse_go_duration(value).ok()?;
            }
            seen.push(f.name.as_str());
        } else if !swallowed && !resolved {
            // cobra's `Find` stops at the first positional that names no child:
            // `mcp agent install --help` is the help of `mcp` (ADR 0037 R5), the
            // later `install` is only an argument of it. The empty word is no word.
            match child(selected, word) {
                Some(next) => selected = next,
                None => resolved = !word.is_empty(),
            }
        }
        i += 1;
    }
    if !help
        || seen
            .iter()
            .any(|name| !flags(selected).iter().any(|f| f.name == *name))
    {
        return None;
    }
    DATA.help
        .contains_key(&selected.path)
        .then_some(selected.path.strip_prefix("symvault ").unwrap_or(""))
}

/// Cobra's `stripFlags` for `command`: the words that are neither flags nor flag
/// values. The help flag is not registered yet while `Find` runs, so a bare `-h` /
/// `--help` takes (only) the next word as its value, like any flag that wants one;
/// `--` ends the scan unless it is taken as such a value; the empty string never
/// counts as a command word.
fn strip_flags<'a>(words: &[&'a str], command: &'static Command) -> Vec<&'a str> {
    let known = flags(command);
    let no_opt_default = |name: &str, short: bool| {
        known.iter().any(|f| {
            f.name != "help"
                && (if short {
                    f.shorthand == name
                } else {
                    f.name == name
                })
                && !f.no_opt_default.is_empty()
        })
    };
    let mut commands = Vec::new();
    let mut i = 0;
    while let Some(&word) = words.get(i) {
        i += 1;
        if word == "--" {
            break;
        }
        let takes_value = !word.contains('=')
            && ((word.starts_with("--") && !no_opt_default(&word[2..], false))
                || (word.starts_with('-') && word.len() == 2 && !no_opt_default(&word[1..], true)));
        if takes_value {
            if words.len() - i <= 1 {
                break;
            }
            i += 1;
        } else if !word.is_empty() && !word.starts_with('-') {
            commands.push(word);
        }
    }
    commands
}

/// Whether cobra's `Find` stops at the root with `unknown command`: the first
/// word left by [`strip_flags`] names no root command (`help` and the hidden
/// `__complete` commands are not part of the artifact tree).
fn unknown_first_command(args: &[std::ffi::OsString]) -> bool {
    let words: Vec<_> = args
        .iter()
        .skip(1)
        .map(|word| word.to_string_lossy())
        .collect();
    let words: Vec<&str> = words.iter().map(|word| &**word).collect();
    strip_flags(&words, root()).first().is_some_and(|first| {
        child(root(), first).is_none() && *first != "help" && !first.starts_with("__")
    })
}

#[cfg(test)]
mod tests {
    use super::{quote_go_bytes, root, strip_flags};

    #[test]
    fn go_quote_of_bytes_writes_each_invalid_byte_as_hex() {
        assert_eq!(quote_go_bytes(b"alpha"), "\"alpha\"");
        assert_eq!(quote_go_bytes(b"alpha\xff"), "\"alpha\\xff\"");
        assert_eq!(quote_go_bytes(b"a\xe2\x82b\"\n"), "\"a\\xe2\\x82b\\\"\\n\"");
        assert_eq!(
            quote_go_bytes("alpha\u{FFFD}".as_bytes()),
            "\"alpha\u{FFFD}\""
        );
        assert_eq!(quote_go_bytes(b"\xf0\x9f"), "\"\\xf0\\x9f\"");
    }

    /// cobra's `stripFlags` with the help flag still unknown: a bare `-h` / `--help`
    /// takes exactly the next word, the empty string is no command, `--` ends it.
    #[test]
    fn strip_flags_follows_cobra_find() {
        fn strip<'a>(words: &[&'a str]) -> Vec<&'a str> {
            strip_flags(words, root())
        }
        assert_eq!(strip(&["--help", "nosuch"]), Vec::<&str>::new());
        assert_eq!(strip(&["--help", "--help", "nosuch"]), ["nosuch"]);
        assert_eq!(strip(&["-h", "--help", "nosuch"]), ["nosuch"]);
        assert_eq!(strip(&["--help", "x", "y"]), ["y"]);
        assert_eq!(strip(&["--help=true", "nosuch"]), ["nosuch"]);
        assert_eq!(strip(&["", "--help"]), Vec::<&str>::new());
        assert_eq!(strip(&["--help", "--", "nosuch"]), ["nosuch"]);
        assert_eq!(strip(&["--json", "nosuch", "--", "x"]), ["nosuch"]);
    }
}
